var n=`0955-katsudon`;var t=`world-0955`;var o=`JP`;var a=`east-asia`;var s=4;var r=66;var d={en:`Katsudon`,ua:`Кацудон`};var l={en:`Katsudon is a Japan dish made with jasmine rice, pork loin, all-purpose flour, chicken egg. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кацудон, страва кухні країни Японія. Основні складники: рис жасмин, свиняча корейка, пшеничне борошно універсальне, куряче яйце. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 22 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 22 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`jasmine-rice`,410,`g`],[`water`,780,`ml`]]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:10,i:[[`pork-loin`,650,`g`],[`all-purpose-flour`,95,`g`],[`chicken-egg`,2,`pcs`],[`panko-breadcrumbs`,200,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,700,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 10 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 10 хвилин до м’якості та готовності.`,t:[`simmering`],m:10,i:[[`dashi-stock`,330,`ml`],[`yellow-onion`,200,`g`],[`mirin`,50,`ml`],[`light-soy-sauce`,45,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 5 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 5 хвилин до готовності й м’якості.`,t:[`poaching`],m:5,i:[[`chicken-egg`,3,`pcs`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:4,i:[]}];var h={slug:n,id:t,country:`JP`,region:a,servings:4,minutes:66,title:d,text:l,steps:u};export{o as country,h as default,t as id,r as minutes,a as region,s as servings,n as slug,u as steps,l as text,d as title};